  const copyable=(o:BoardObject)=>!(o.type==='region'||o.type==='deck'||(o.type==='card'&&(!o.faceUp||o.peek)));
  const selectedDice=selectedObjects.filter((o):o is DieObject=>o.type==='die');
  const selectedRegion=selectedObjects.length===1&&selectedObjects[0].type==='region'?selectedObjects[0]:undefined;
  const myHand=snapshot.objects.find((o):o is RegionObject=>o.type==='region'&&o.ownerId===me.id);
  const blockedForMe=(o:BoardObject)=>{if(me.isTutor)return false;if(o.type==='region')return o.ownerId!==me.id;const hand=handOf(snapshot.objects,o);return Boolean(hand&&hand.ownerId!==me.id);};
