  useEffect(()=>{const nodes=selected.map(id=>stageRef.current?.findOne(`#${id}`)).filter(Boolean) as Konva.Node[];trRef.current?.nodes(nodes);trRef.current?.getLayer()?.batchDraw();},[selected,snapshot.objects]);
  useEffect(()=>{const received=new Set(snapshot.objects.map(o=>o.id));pendingObjects.current=pendingObjects.current.filter(o=>!received.has(o.id));},[snapshot.objects]);
